dashboard.definition:
{
	"title": "Hybrid Mesh Firewalling",
	"description": "Unify firewall posture, enforcement, and workload protection across the hybrid mesh.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#16283c",
				"strokeColor": "rgba(53,207,245,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Hybrid Mesh Firewalling",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/hybrid-mesh-firewalling.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e8f1fb",
				"markdown": "# Hybrid Mesh Firewalling\nUnify firewall posture, enforcement, and workload protection across the hybrid mesh."
			}
		},
		"viz_hmf_fw_blocked": {
			"type": "splunk.singlevalue",
			"title": "Blocked Connections",
			"dataSources": {
				"primary": "ds_hmf_fw_blocked"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('blocked') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#ff9a4a"
			},
			"description": "Counts how many unique connection attempts were blocked by the firewall, treating repeated blocks of the same connection as one."
		},
		"viz_hmf_ftd_feed": {
			"type": "splunk.singlevalueradial",
			"title": "FTD Feed Age",
			"dataSources": {
				"primary": "ds_hmf_ftd_feed"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('age_minutes') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "> primary | seriesByName('age_minutes') | lastPoint() | rangeValue(staleness)",
				"unit": "min"
			},
			"context": {
				"staleness": [
					{
						"to": 30,
						"value": "#8bd45b"
					},
					{
						"from": 30,
						"to": 90,
						"value": "#ff9a4a"
					},
					{
						"from": 90,
						"value": "#ff7169"
					}
				]
			},
			"description": "Staleness monitor for Cisco FTD firewall feeds covering syslog, advanced JSON connection events, and DNS logs. Any production firewall sees continuous traffic - silence beyond 30 minutes means the feed is broken, not the…"
		},
		"viz_hmf_fmc_count": {
			"type": "splunk.singlevalue",
			"title": "FMC Firewalls",
			"dataSources": {
				"primary": "ds_hmf_fmc_count"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('firewall_count') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#53bfff"
			},
			"description": "Total count of unique Cisco Firepower/FTD firewalls actively reporting to Cisco FMC, based on distinct Device UUIDs seen in FMC syslog, providing the on-premises firewall infrastructure footprint KPI."
		},
		"viz_hmf_sse_total": {
			"type": "splunk.singlevalue",
			"title": "SSE Security Events",
			"dataSources": {
				"primary": "ds_hmf_sse_total"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"majorFontSize": 36,
				"majorValue": "> primary | seriesByName('total_events') | lastPoint()",
				"shouldAbbreviateMajorValue": true,
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorColor": "#14b8a6"
			},
			"description": "Total count of all security events across Cisco Secure Service Edge (SSE) , combining cloud firewall, DNS security, and web proxy telemetry into a single top-level KPI."
		},
		"viz_hmf_unified_blocks": {
			"type": "splunk.line",
			"title": "Unified Blocks Trend",
			"dataSources": {
				"primary": "ds_hmf_unified_blocks"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#ff7169",
					"#ff9a4a",
					"#53bfff",
					"#7c3aed"
				],
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			},
			"description": "Creates a unified block trend across Meraki security events, SD-WAN UTD, Secure Access firewall events, and Secure Firewall/ASA-style feeds."
		},
		"viz_hmf_fmc_activity": {
			"type": "splunk.area",
			"title": "FMC Activity Trend",
			"dataSources": {
				"primary": "ds_hmf_fmc_activity"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#8bd45b",
					"#ff7169",
					"#53bfff",
					"#64748b"
				],
				"stackMode": "stacked",
				"lineWidth": 2,
				"nullValueDisplay": "gaps"
			},
			"description": "Hourly time-series trend of Cisco FMC firewall actions and advanced connection observations , enabling operators to correlate enforcement spikes with overall flow activity."
		},
		"viz_hmf_dns_categories": {
			"type": "splunk.bar",
			"title": "SSE DNS Blocked Categories",
			"dataSources": {
				"primary": "ds_hmf_dns_categories"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#ff7169",
					"#ff9a4a",
					"#7c3aed"
				]
			},
			"description": "Top DNS content categories responsible for blocked queries in Cisco Umbrella/SSE, showing which threat categories and policy-driven classifications are generating the most DNS enforcement activity."
		},
		"viz_hmf_enforcement_coverage": {
			"type": "splunk.table",
			"title": "Enforcement Coverage by Site",
			"dataSources": {
				"primary": "ds_hmf_enforcement_coverage"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Shows Hybrid Mesh Firewalling enforcement coverage by site using Meraki device inventory and SD-WAN UTD activity."
		},
		"viz_hmf_fmc_top_rules": {
			"type": "splunk.bar",
			"title": "Top FMC Access Rule Hits",
			"dataSources": {
				"primary": "ds_hmf_fmc_top_rules"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"legendDisplay": "right",
				"showYMajorGridLines": true,
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": [
					"#ff9a4a",
					"#53bfff"
				]
			},
			"description": "Top Cisco FMC access control rules by hit count , exposing which rules are handling the highest traffic volumes and whether those rules are permitting or denying connections."
		},
		"viz_hmf_dlp_findings": {
			"type": "splunk.table",
			"title": "Secure Access DLP Findings",
			"dataSources": {
				"primary": "ds_hmf_dlp_findings"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Summarizes Secure Access DLP findings by severity, action, rule, data classification, application, and traffic direction."
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "**Audience:** Firewall, network-security, and SOC teams  •  **Sources:** Secure Firewall, Meraki, SD-WAN UTD, Secure Access, and ASA telemetry  •  **Reading guide:** Start with block volume and feed freshness, then compare trends and site coverage.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "### Enforcement posture\nStart with block volume and feed freshness, then compare trends and site coverage."
			}
		}
	},
	"dataSources": {
		"ds_hmf_fw_blocked": {
			"name": "Executive - Firewall Blocked Count",
			"options": {
				"ref": "executive_dashboard_firewall_blocked_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_ftd_feed": {
			"name": "Feed Monitor - FTD Firewall - Stream Staleness - Signal Rail KPI",
			"options": {
				"ref": "feed_monitor_ftd_firewall_staleness",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_fmc_count": {
			"name": "Secure Networking chain - FMC firewall count",
			"options": {
				"ref": "secure_networking_infra_fmc_firewall_count",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_sse_total": {
			"name": "Secure Networking - SSE Total Security Events",
			"options": {
				"ref": "secure_networking_sse_total_security_events",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_unified_blocks": {
			"name": "Secure Networking - HMF Unified Blocks Trend",
			"options": {
				"ref": "secure_networking_hmf_unified_blocks_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_fmc_activity": {
			"name": "Secure Networking chain - FMC activity trend",
			"options": {
				"ref": "secure_networking_fmc_activity_trend",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_dns_categories": {
			"name": "Secure Networking - SSE DNS Blocked Categories",
			"options": {
				"ref": "secure_networking_sse_dns_blocked_categories",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_enforcement_coverage": {
			"name": "Secure Networking - HMF Enforcement Coverage by Site",
			"options": {
				"ref": "secure_networking_hmf_enforcement_coverage_by_site",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_fmc_top_rules": {
			"name": "Secure Networking chain - FMC top rules",
			"options": {
				"ref": "secure_networking_fmc_top_rules_hit",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_hmf_dlp_findings": {
			"name": "Secure Networking - Secure Access DLP Findings",
			"options": {
				"ref": "secure_networking_secure_access_dlp_findings",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#07101d",
					"display": "auto-scale",
					"height": 1914,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 118
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 19,
							"w": 80,
							"h": 80
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 132,
							"y": 8,
							"w": 1268,
							"h": 102
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 138,
							"w": 1400,
							"h": 92
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 250,
							"w": 1400,
							"h": 72
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_fw_blocked",
						"position": {
							"x": 20,
							"y": 342,
							"w": 335,
							"h": 228
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_ftd_feed",
						"position": {
							"x": 375,
							"y": 342,
							"w": 335,
							"h": 228
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_fmc_count",
						"position": {
							"x": 730,
							"y": 342,
							"w": 335,
							"h": 228
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_sse_total",
						"position": {
							"x": 1085,
