					},
					{
						"item": "viz_hmf_fmc_activity",
						"position": {
							"x": 730,
							"y": 590,
							"w": 690,
							"h": 388
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_dns_categories",
						"position": {
							"x": 20,
							"y": 998,
							"w": 690,
							"h": 438
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_enforcement_coverage",
						"position": {
							"x": 730,
							"y": 998,
							"w": 690,
							"h": 438
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_fmc_top_rules",
						"position": {
							"x": 20,
							"y": 1456,
							"w": 690,
							"h": 438
						},
						"type": "block"
					},
					{
						"item": "viz_hmf_dlp_findings",
						"position": {
							"x": 730,
							"y": 1456,
							"w": 690,
							"h": 438
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
